@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Planner extends Employee {
  + username : string
  + password : string
}

class AdministrativeStaff extends Employee {
  + username : string
  + password : string
  + fieldOfActivity : string
}

class Driver extends Employee {
}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlateNumber : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}
class SmallVan extends Vehicle {}
class LoadingPlatform extends Vehicle {}
class BoxTruck extends Vehicle {}

class Repair {
  + duration : string
  + cost : double
}

class RepairShop {
  + name : string
  + address : string
}

class Order {
  + packageSize : string
  + pickUpAddress : string
  + deliveryAddress : string
  + startTime : datetime
  + finishTime : datetime
  + comment : string
}

class Assignment {
}

Employee "1" -- "0..*" Repair : takes vehicle to
Repair "0..*" -- "1" Vehicle : involves
Repair "0..*" -- "1" RepairShop : at

Customer "1" -- "0..*" Order : is client of
PartnerCompany "0..*" -- "0..*" Order : places order with

Order "0..*" -- "1" Vehicle : assigned to
Order "0..*" -- "1" Planner : assigned by
Order "0..*" -- "1" Driver : completed by
Order "0..*" -- "1" Vehicle : completed with

Driver "1" -- "0..*" Order : is assigned to

@enduml

